import type { Bank } from "./types";

// AFM practice bank: original questions; numericals verified twice.
const bank: Bank = {
  questions: [
    { id: "afm-001", chapter: "1. Financial Policy and Corporate Strategy", prompt: "A company has a net profit margin of 8%, asset turnover of 1.5 times and an equity multiplier (assets ÷ equity) of 1.25. It retains 60% of its earnings. Using g = b × r, where r is ROE (treat the ratios as based on opening equity), what is its sustainable growth rate?", options: ["7.2%", "9.0%", "6.0%", "15.0%"], answer: 1, explanation: "ROE = 8% × 1.5 × 1.25 = 15%; SGR = 0.60 × 15% = 9%. 7.2% wrongly uses ROA (12%) and 6% uses the payout ratio instead of retention." },
    { id: "afm-002", chapter: "1. Financial Policy and Corporate Strategy", prompt: "A firm wants to grow faster than its sustainable growth rate without issuing any new equity. Which of the following would NOT help it close the gap?", options: ["Increasing its retention ratio", "Improving its asset turnover", "Increasing its dividend payout ratio", "Raising its debt-equity ratio"], answer: 2, explanation: "SGR = retention × ROE; a higher payout cuts retention and lowers SGR, while higher retention, turnover or leverage all raise it." },
    { id: "afm-003", chapter: "1. Financial Policy and Corporate Strategy", prompt: "A company earns an ROE of 16% and its board targets an annual growth rate of 12% with no external equity and an unchanged capital structure. Using g = b × r, what is the maximum dividend payout ratio it can maintain?", options: ["75%", "33.33%", "12%", "25%"], answer: 3, explanation: "Required retention b = 12% ÷ 16% = 75%, so payout = 1 − 0.75 = 25%. 75% is the retention ratio, not the payout." },
    { id: "afm-004", chapter: "2. Risk Management", prompt: "A portfolio worth ₹50 crore has a daily return standard deviation of 1.2%. Assuming normally distributed, independent daily returns, what is its 10-day VaR at 99% confidence (z = 2.33), to two decimals?", options: ["₹1.40 crore", "₹13.98 crore", "₹4.42 crore", "₹3.12 crore"], answer: 2, explanation: "1-day VaR = 50 × 1.2% × 2.33 = 1.398 crore; 10-day = 1.398 × √10 = 4.42 crore. Multiplying by 10 instead of √10 gives 13.98." },
    { id: "afm-005", chapter: "2. Risk Management", prompt: "A ₹20 lakh equity position has an annual volatility of 25%. Assuming 250 trading days and z = 1.65 for 95% confidence, what is its 1-day VaR to the nearest rupee?", options: ["₹8,25,000", "₹33,000", "₹3,162", "₹52,178"], answer: 3, explanation: "Daily σ = 25% ÷ √250 = 1.5811%; VaR = 20,00,000 × 1.5811% × 1.65 = ₹52,178." },
    { id: "afm-006", chapter: "2. Risk Management", prompt: "Which of the following statements about Value at Risk is NOT correct?", options: ["Under i.i.d. normal returns, VaR scales with the square root of the holding period", "VaR is the maximum loss that the position can suffer in any circumstances", "For the same position, 99% VaR is higher than 95% VaR", "VaR says nothing about the size of losses beyond the VaR threshold"], answer: 1, explanation: "VaR is the loss not exceeded at a chosen confidence level over a period; losses beyond it can and do occur." },
    { id: "afm-007", chapter: "2. Risk Management", prompt: "Two desks have stand-alone 1-day VaRs of ₹10 lakh and ₹6 lakh (both computed with the same normal z-value). If the correlation between their returns is 0.5, what is the combined VaR?", options: ["₹16 lakh", "₹14 lakh", "₹11.66 lakh", "₹12 lakh"], answer: 1, explanation: "Combined VaR = √(10² + 6² + 2 × 0.5 × 10 × 6) = √196 = ₹14 lakh; ₹16 lakh assumes perfect correlation and ₹11.66 lakh assumes zero." },
    { id: "afm-008", chapter: "2. Risk Management", prompt: "A position's 1-day 95% VaR is ₹3,30,000 using z = 1.65. Under the normal VaR model, what is its 1-day 99% VaR using z = 2.33?", options: ["₹3,43,895", "₹2,33,672", "₹4,66,000", "₹5,35,000"], answer: 2, explanation: "Daily σ in rupees = 3,30,000 ÷ 1.65 = 2,00,000; 99% VaR = 2,00,000 × 2.33 = ₹4,66,000." },
    { id: "afm-009", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "A project costs ₹10,00,000 and is expected to generate ₹4,00,000 a year for 3 years. The certainty-equivalent coefficients are 0.9, 0.8 and 0.7 for years 1 to 3, and the risk-free rate is 6%. What is the NPV (approximately)?", options: ["₹69,205", "−₹1,97,896", "−₹40,000", "−₹1,40,485"], answer: 3, explanation: "CE flows 3.6, 3.2, 2.8 lakh discounted at 6% = ₹8,59,515, less ₹10,00,000. Discounting CE flows at a risky rate double-counts risk (−1,97,896)." },
    { id: "afm-010", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "A project costs ₹9,00,000 and yields ₹3,00,000 a year for 4 years. The risk-free rate is 7% and management adds a 5% risk premium. PVAF(12%, 4) = 3.037 and PVAF(7%, 4) = 3.387. What is the NPV under the risk-adjusted discount rate method?", options: ["₹1,16,100", "₹11,100", "₹65,295", "₹8,700"], answer: 1, explanation: "RADR = 7% + 5% = 12%; NPV = 3,00,000 × 3.037 − 9,00,000 = ₹11,100. ₹1,16,100 discounts at the risk-free rate; ₹65,295 cuts flows by 5% instead of adjusting the rate." },
    { id: "afm-011", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "A project has PV of sales revenue ₹15,00,000, PV of variable costs ₹9,00,000, PV of fixed costs ₹2,00,000 and an initial outlay of ₹2,80,000. By what percentage can sales volume fall before NPV becomes zero?", options: ["8%", "13.33%", "20%", "42.86%"], answer: 2, explanation: "NPV = 1,20,000; volume affects contribution (15 − 9 = 6 lakh), so 1.2 ÷ 6 = 20%. 8% is the selling-price sensitivity, 13.33% variable cost." },
    { id: "afm-012", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "An investment of ₹50 lakh has a 60% chance of PV inflows of ₹90 lakh and a 40% chance of ₹30 lakh. If the bad state occurs the firm can abandon the project and realise ₹40 lakh (PV). What is the value of the abandonment option?", options: ["₹20 lakh", "₹4 lakh", "₹16 lakh", "₹10 lakh"], answer: 1, explanation: "ENPV without option = 54 + 12 − 50 = 16; with option = 54 + 16 − 50 = 20; option value = 20 − 16 = ₹4 lakh (not the full ₹10 lakh gain)." },
    { id: "afm-013", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "A project's NPV is −₹20 lakh with probability 0.3, ₹40 lakh with probability 0.5 and ₹100 lakh with probability 0.2. What is the standard deviation of NPV?", options: ["₹34 lakh", "₹49 lakh", "₹36 lakh", "₹42 lakh"], answer: 3, explanation: "Expected NPV = 34; variance = 0.3(−54)² + 0.5(6)² + 0.2(66)² = 1,764; σ = √1,764 = ₹42 lakh. ₹34 lakh is the mean, not σ." },
    { id: "afm-014", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "Under Hillier's model, a project's year-1 and year-2 cash flows have standard deviations of ₹1,000 and ₹1,200 and are independent of each other. At a 10% risk-free rate, what is the standard deviation of NPV (nearest rupee)?", options: ["₹1,901", "₹1,562", "₹1,345", "₹2,200"], answer: 2, explanation: "σ² = 1,000²/1.1² + 1,200²/1.1⁴ = 18,09,986; σ = ₹1,345. ₹1,901 is the perfectly-correlated case (sum of discounted σs)." },
    { id: "afm-015", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "A cash flow of ₹2,00,000 in today's prices will arise at the end of year 3. Inflation is 6% a year and the real discount rate is 10%. What is its present value (nearest rupee)?", options: ["₹1,26,164", "₹1,78,966", "₹1,58,571", "₹1,50,263"], answer: 3, explanation: "Discount the real flow at the real rate: 2,00,000 ÷ 1.1³ = ₹1,50,263 (same as inflating it and discounting at nominal 16.6%). Mixing real and nominal gives the others." },
    { id: "afm-016", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "Which of the following statements about real options in capital budgeting is NOT correct?", options: ["An option to abandon resembles a put option on the project's value", "An option to expand resembles a call option on follow-on investment", "A static NPV that ignores managerial flexibility may undervalue a project", "Higher volatility of project cash flows reduces the value of an option to expand"], answer: 3, explanation: "Like any option, an expansion option gains value as volatility rises, because the upside is captured and the downside is avoided." },
    { id: "afm-017", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "A proxy firm in the new line of business has an equity beta of 1.5 and a debt-equity ratio of 0.5. Your firm will fund the project at a debt-equity ratio of 1.0. Tax rate is 25% and debt is risk-free. What equity beta should be used for the project?", options: ["1.09", "2.00", "1.50", "1.91"], answer: 3, explanation: "Asset beta = 1.5 ÷ (1 + 0.5 × 0.75) = 1.091; relevered = 1.091 × (1 + 1.0 × 0.75) = 1.91. 2.00 ignores tax; 1.09 is the asset beta." },
    { id: "afm-018", chapter: "3. Advanced Capital Budgeting Decisions", prompt: "A project's cash flows are estimated in nominal terms. The real required return is 8% and expected inflation is 5%. What nominal discount rate should be applied?", options: ["13.40%", "13.00%", "3.00%", "2.86%"], answer: 0, explanation: "Fisher: (1.08 × 1.05) − 1 = 13.40%. Simply adding the two (13%) ignores the cross term." },
    { id: "afm-019", chapter: "4. Security Analysis", prompt: "If a stock market is efficient in the semi-strong form (but not the strong form), which of the following could still earn consistent abnormal returns?", options: ["Analysing past price and volume charts", "Studying published annual reports", "Reacting to dividend announcements after release", "Trading on material non-public information"], answer: 3, explanation: "Semi-strong efficiency prices in all public information, past prices included; only private (insider) information can still earn abnormal returns." },
    { id: "afm-020", chapter: "4. Security Analysis", prompt: "A stock's 10-day exponential moving average (EMA) was ₹200 yesterday. Today it closes at ₹212. Using a smoothing factor of 2 ÷ (n + 1), what is today's EMA (two decimals)?", options: ["₹201.20", "₹206.00", "₹202.18", "₹210.91"], answer: 2, explanation: "α = 2 ÷ 11 = 0.1818; EMA = 200 + 0.1818 × (212 − 200) = ₹202.18. ₹201.20 uses 1/n (0.10) as the weight." },
    { id: "afm-021", chapter: "4. Security Analysis", prompt: "High-grade corporate bonds yield 7.2% and intermediate-grade bonds yield 8.0%. What is the confidence index, and how is a rise in it usually read?", options: ["1.11; a rise is read as bullish", "0.90; a rise is read as bearish", "0.90; a rise is read as bullish", "1.11; a rise is read as bearish"], answer: 2, explanation: "Confidence index = high-grade yield ÷ lower-grade yield = 7.2 ÷ 8.0 = 0.90; a rising index means a narrowing risk spread, read as bullish." },
    { id: "afm-022", chapter: "4. Security Analysis", prompt: "A company pays out 40% of earnings, its cost of equity is 13% and it is expected to grow at 8% for ever. What is its justified trailing P/E ratio (on current EPS)?", options: ["8.64", "8.00", "3.08", "7.41"], answer: 0, explanation: "Forward P/E = 0.40 ÷ (0.13 − 0.08) = 8.0; trailing P/E = 8.0 × 1.08 = 8.64 because P₀ = D₀(1 + g) ÷ (ke − g)." },
    { id: "afm-023", chapter: "4. Security Analysis", prompt: "Under Dow Theory, which of the following best describes a secondary reaction?", options: ["A move against the primary trend that typically retraces one-third to two-thirds of the prior primary move", "A day-to-day fluctuation of no forecasting significance", "A long-term trend lasting a year or more that sets the market's direction", "A move confirmed only when the industrial and transport averages diverge"], answer: 0, explanation: "Secondary reactions are intermediate corrections against the primary trend, usually retracing 1/3 to 2/3 of it; daily moves are minor trends." },
    { id: "afm-024", chapter: "5. Security Valuation", prompt: "A ₹1,000 bond pays a 10% annual coupon and matures in 3 years. What is its price if the yield to maturity is 12% (two decimals)?", options: ["₹1,000.00", "₹952.50", "₹951.96", "₹1,049.74"], answer: 2, explanation: "Price = 100/1.12 + 100/1.12² + 1,100/1.12³ = 89.29 + 79.72 + 782.96 = ₹951.96; YTM above coupon means a discount." },
    { id: "afm-025", chapter: "5. Security Valuation", prompt: "A 3-year ₹1,000 bond with a 10% annual coupon trades at par (YTM 10%). What is its modified duration (two decimals)?", options: ["2.74", "3.00", "2.27", "2.49"], answer: 3, explanation: "Macaulay = (90.91×1 + 82.64×2 + 826.45×3) ÷ 1,000 = 2.7355; modified = 2.7355 ÷ 1.10 = 2.49. 2.74 is Macaulay duration." },
    { id: "afm-026", chapter: "5. Security Valuation", prompt: "A bond has modified duration of 6 and convexity of 50. Using ΔP/P = −MD × Δy + ½ × C × (Δy)², what is the estimated price change if yields rise by 100 basis points?", options: ["−6.00%", "−5.75%", "−6.25%", "−5.50%"], answer: 1, explanation: "ΔP/P = −6 × 0.01 + 0.5 × 50 × 0.0001 = −6% + 0.25% = −5.75%; convexity always adds to price, cushioning the fall." },
    { id: "afm-027", chapter: "5. Security Valuation", prompt: "A ₹1,000 bond with a 9% annual coupon and 5 years to maturity trades at ₹920. Using the approximation YTM = [C + (F − P)/n] ÷ [(F + P)/2], what is the YTM (two decimals)?", options: ["9.78%", "11.52%", "10.60%", "11.04%"], answer: 3, explanation: "YTM ≈ (90 + 80/5) ÷ (1,920/2) = 106 ÷ 960 = 11.04%. 9.78% is current yield (90/920)." },
    { id: "afm-028", chapter: "5. Security Valuation", prompt: "A share has just paid a dividend of ₹5. Dividends will grow at 15% for 2 years and at 6% for ever thereafter. The cost of equity is 12%. What is the intrinsic value today (two decimals)?", options: ["₹93.04", "₹116.82", "₹103.53", "₹88.33"], answer: 2, explanation: "D1 5.75, D2 6.6125, D3 7.0093; P2 = 7.0093 ÷ 0.06 = 116.82; value = 5.75/1.12 + (6.6125 + 116.82)/1.12² = ₹103.53." },
    { id: "afm-029", chapter: "5. Security Valuation", prompt: "A company reports net income ₹50 crore, depreciation ₹10 crore, capital expenditure ₹25 crore, increase in working capital ₹5 crore and net new borrowing ₹8 crore. What is its free cash flow to equity?", options: ["₹38 crore", "₹30 crore", "₹22 crore", "₹48 crore"], answer: 0, explanation: "FCFE = 50 + 10 − 25 − 5 + 8 = ₹38 crore; net borrowing is added because it is cash available to shareholders." },
    { id: "afm-030", chapter: "5. Security Valuation", prompt: "A firm's EBIT is ₹80 crore, tax rate 25%, depreciation ₹12 crore, capex ₹20 crore and increase in working capital ₹4 crore. FCFF will grow at 5% for ever and WACC is 10%. What is the value of the firm today?", options: ["₹1,008 crore", "₹960 crore", "₹504 crore", "₹1,200 crore"], answer: 0, explanation: "FCFF₀ = 80 × 0.75 + 12 − 20 − 4 = 48; FCFF₁ = 50.4; value = 50.4 ÷ (0.10 − 0.05) = ₹1,008 crore. ₹960 crore forgets to grow FCFF." },
    { id: "afm-031", chapter: "5. Security Valuation", prompt: "A company's next-year EPS is ₹10. It pays out 40%, earns 15% on reinvested equity and its cost of equity is 12.5%. What is the present value of growth opportunities (two decimals)?", options: ["₹114.29", "₹80.00", "₹14.29", "₹34.29"], answer: 3, explanation: "g = 0.6 × 15% = 9%; P = 4 ÷ 0.035 = 114.29; no-growth value = 10 ÷ 0.125 = 80; PVGO = 114.29 − 80 = ₹34.29." },
    { id: "afm-032", chapter: "5. Security Valuation", prompt: "A ₹1,000 convertible debenture is convertible into 25 equity shares. The share trades at ₹36 and the debenture at ₹1,050. What is the conversion premium as a percentage of conversion value (two decimals)?", options: ["14.29%", "16.67%", "5.00%", "42.00%"], answer: 1, explanation: "Conversion value = 25 × 36 = 900; premium = 1,050 − 900 = 150; 150 ÷ 900 = 16.67%. 14.29% wrongly divides by the debenture price." },
    { id: "afm-033", chapter: "5. Security Valuation", prompt: "Other things equal, which of the following statements about Macaulay duration is NOT correct?", options: ["The duration of a zero-coupon bond equals its maturity", "Duration falls as the yield to maturity rises", "Duration rises as the coupon rate rises", "A coupon bond's duration is less than its maturity"], answer: 2, explanation: "Higher coupons put more value in early cash flows, so duration falls as the coupon rises; the other three statements are true." },
    { id: "afm-034", chapter: "6. Portfolio Management", prompt: "The risk-free rate is 6%, the market return is 13% and a stock's beta is 1.3. An analyst forecasts the stock will return 16%. What does CAPM indicate?", options: ["Required return 15.1%; the stock is overpriced (alpha −0.9%)", "Required return 16.9%; the stock is overpriced (alpha −0.9%)", "Required return 15.1%; the stock is underpriced (alpha +0.9%)", "Required return 16.9%; the stock is underpriced (alpha +0.9%)"], answer: 2, explanation: "Required = 6 + 1.3 × 7 = 15.1%; expected 16% lies above the SML, so the stock is underpriced and should be bought." },
    { id: "afm-035", chapter: "6. Portfolio Management", prompt: "A portfolio holds 40% in a stock with beta 1.5, 35% in a stock with beta 0.8 and 25% in a stock with beta 1.2. What is the portfolio beta?", options: ["1.17", "1.18", "1.24", "1.12"], answer: 1, explanation: "Portfolio beta = 0.40 × 1.5 + 0.35 × 0.8 + 0.25 × 1.2 = 0.60 + 0.28 + 0.30 = 1.18." },
    { id: "afm-036", chapter: "6. Portfolio Management", prompt: "A portfolio has 60% in asset A (σ = 20%) and 40% in asset B (σ = 30%). The correlation between them is 0.2. What is the portfolio standard deviation (two decimals)?", options: ["18.59%", "24.00%", "16.97%", "19.80%"], answer: 0, explanation: "Variance = 0.36×400 + 0.16×900 + 2×0.6×0.4×0.2×20×30 = 345.6; σ = 18.59%. 24% is the weighted average (ρ = 1)." },
    { id: "afm-037", chapter: "6. Portfolio Management", prompt: "Asset A has σ = 15% and asset B has σ = 25%, with correlation −0.2. What proportion in A gives the minimum-variance portfolio?", options: ["73.5%", "62.5%", "37.5%", "70%"], answer: 3, explanation: "Cov = −0.2 × 15 × 25 = −75; wA = (625 + 75) ÷ (225 + 625 + 150) = 700 ÷ 1,000 = 70%. 73.5% ignores the correlation." },
    { id: "afm-038", chapter: "6. Portfolio Management", prompt: "A fund earned 14% with a beta of 0.8 and σ of 16%. The risk-free rate is 6% and the market returned 12%. What is the fund's Jensen's alpha?", options: ["8.0%", "3.2%", "2.0%", "1.2%"], answer: 1, explanation: "CAPM return = 6 + 0.8 × (12 − 6) = 10.8%; alpha = 14 − 10.8 = 3.2%. 8% is just the excess return over the risk-free rate." },
    { id: "afm-039", chapter: "6. Portfolio Management", prompt: "Fund X returned 15% (σ 20%, β 1.0) and Fund Y returned 13% (σ 14%, β 1.2). The risk-free rate is 6%. Which statement is correct?", options: ["X ranks higher on Sharpe, Y ranks higher on Treynor, so Y carries more unsystematic risk", "Y ranks higher on both Sharpe and Treynor", "Y ranks higher on Sharpe, X ranks higher on Treynor, so X carries more unsystematic risk", "X ranks higher on both Sharpe and Treynor"], answer: 2, explanation: "Sharpe X 0.45, Y 0.50; Treynor X 9.0, Y 5.83. X looks better per unit of beta but worse per unit of total risk, so it is less diversified." },
    { id: "afm-040", chapter: "6. Portfolio Management", prompt: "A stock has σ = 30% and β = 1.2; the market σ is 20%. What proportion of the stock's total variance is systematic?", options: ["80%", "64%", "36%", "60%"], answer: 1, explanation: "Systematic variance = 1.2² × 20² = 576; total = 900; 576 ÷ 900 = 64%. 80% compares standard deviations (24/30), not variances." },
    { id: "afm-041", chapter: "6. Portfolio Management", prompt: "The risk-free rate is 6%, the market portfolio returns 14% with σ of 20%. What is the expected return of an efficient portfolio on the CML with σ of 15%, and how is it built?", options: ["12%; 75% in the market and 25% borrowed at the risk-free rate", "10.5%; 75% in the market and 25% lent at the risk-free rate", "12%; 75% in the market portfolio and 25% lent at the risk-free rate", "16%; 125% in the market financed by borrowing"], answer: 2, explanation: "Return = 6 + (14 − 6)/20 × 15 = 12%; weight in market = 15/20 = 75%, so 25% is lent (invested) at the risk-free rate." },
    { id: "afm-042", chapter: "6. Portfolio Management", prompt: "Under a two-factor APT model, the risk-free rate is 6%, the factor risk premia are 4% (factor 1) and 2.5% (factor 2), and a stock's sensitivities are 1.2 and 0.8. What is its expected return?", options: ["16.4%", "6.8%", "10.8%", "12.8%"], answer: 3, explanation: "E(R) = 6 + 1.2 × 4 + 0.8 × 2.5 = 6 + 4.8 + 2.0 = 12.8%. Premia are already excess returns, so Rf is not deducted from them." },
    { id: "afm-043", chapter: "6. Portfolio Management", prompt: "A stock's return has σ = 30% and a correlation of 0.6 with the market; the market σ is 16%. What is the stock's beta (three decimals)?", options: ["1.875", "1.125", "0.320", "0.675"], answer: 1, explanation: "β = ρ × σi ÷ σm = 0.6 × 30 ÷ 16 = 1.125. 1.875 omits the correlation." },
    { id: "afm-044", chapter: "6. Portfolio Management", prompt: "Under a CPPI strategy with a floor of ₹80 lakh and a multiplier of 2, a ₹100 lakh portfolio is rebalanced. If equities then fall 10% before the next rebalance, how much will be in equity after rebalancing?", options: ["₹36 lakh", "₹32 lakh", "₹40 lakh", "₹28 lakh"], answer: 1, explanation: "Initial equity = 2 × (100 − 80) = 40; after a 10% fall equity is 36, portfolio 96; new equity = 2 × (96 − 80) = ₹32 lakh (sell 4 lakh)." },
    { id: "afm-045", chapter: "6. Portfolio Management", prompt: "Which of the following statements about the Capital Market Line (CML) and Security Market Line (SML) is NOT correct?", options: ["The CML measures risk by standard deviation", "The SML measures risk by beta", "The CML can be used to price individual securities, including inefficient portfolios", "In equilibrium, every correctly priced security lies on the SML"], answer: 2, explanation: "Only efficient portfolios lie on the CML; individual securities and inefficient portfolios are priced by the SML using beta." },
    { id: "afm-046", chapter: "6. Portfolio Management", prompt: "Under Sharpe's single-index model, a stock has β = 1.1, the market σ is 18% and the residual variance is 0.012. What is the stock's total standard deviation (two decimals)?", options: ["19.80%", "25.94%", "22.63%", "11.85%"], answer: 2, explanation: "Total variance = 1.1² × 0.0324 + 0.012 = 0.051204; σ = 22.63%. 19.80% is only the systematic part (β × σm)." },
    { id: "afm-047", chapter: "7. Securitization", prompt: "In a true-sale securitisation, what is the main reason the receivables are transferred to a separate Special Purpose Vehicle rather than kept on the originator's books?", options: ["To let the originator keep full control of the collections", "To raise the credit rating of the originator itself", "To avoid the need for any credit enhancement", "To make the assets bankruptcy-remote from the originator"], answer: 3, explanation: "Investors look only to the pool; isolating it in an SPV protects their claims if the originator fails, which is why the transfer must be a true sale." },
    { id: "afm-048", chapter: "7. Securitization", prompt: "Which securitised instrument allows the SPV to restructure the pool's cash flows into tranches with different maturities, instead of simply passing them through to investors?", options: ["Pass Through Certificate (PTC)", "Interest-only strip", "Principal-only strip", "Pay Through Security (PTS)"], answer: 3, explanation: "A PTC passes collections straight through pro rata; a PTS lets the SPV reshape the cash flows into tranches of differing maturity." },
    { id: "afm-049", chapter: "7. Securitization", prompt: "A ₹100 crore receivables pool backs a senior tranche of ₹80 crore and a junior tranche of ₹15 crore; the originator retains a ₹5 crore first-loss piece. If pool losses are ₹14 crore, what percentage of the junior tranche is lost?", options: ["93.33%", "60%", "14%", "11.25%"], answer: 1, explanation: "Losses hit the ₹5 crore first-loss piece first; the remaining ₹9 crore falls on the junior tranche: 9 ÷ 15 = 60%. The senior tranche is untouched." },
    { id: "afm-050", chapter: "7. Securitization", prompt: "If market interest rates fall sharply and mortgage prepayments speed up, what is the likely effect on stripped mortgage-backed securities?", options: ["Interest-only strips fall in value; principal-only strips rise", "Interest-only strips rise in value; principal-only strips fall", "Both strips rise in value", "Both strips fall in value"], answer: 0, explanation: "Faster prepayment shrinks the balance on which interest is earned, hurting IO holders, while PO holders get their principal back sooner." },
    { id: "afm-051", chapter: "8. Mutual Funds", prompt: "A scheme holds investments at market value ₹250 crore, cash ₹10 crore, receivables ₹5 crore and accrued income ₹3 crore. Its liabilities are ₹8 crore plus ₹2 crore of accrued expenses. It has 12 crore units outstanding. What is the NAV per unit?", options: ["₹22.33", "₹21.50", "₹21.67", "₹20.83"], answer: 1, explanation: "Net assets = 268 − 10 = ₹258 crore; NAV = 258 ÷ 12 = ₹21.50. ₹22.33 ignores all liabilities." },
    { id: "afm-052", chapter: "8. Mutual Funds", prompt: "A unit's NAV moved from ₹20 to ₹22 during the year, and the fund paid a dividend of ₹1.00 and a capital gains distribution of ₹0.50 per unit. What was the holding period return?", options: ["10.0%", "15.0%", "17.5%", "15.9%"], answer: 2, explanation: "Return = (22 − 20 + 1.00 + 0.50) ÷ 20 = 3.5 ÷ 20 = 17.5%. 10% counts only the NAV change." },
    { id: "afm-053", chapter: "8. Mutual Funds", prompt: "An investor holds 1,000 units bought at NAV ₹12. A dividend of ₹1.20 per unit is reinvested at the ex-dividend NAV of ₹13. The year-end NAV is ₹13.50. What is her return for the year (two decimals)?", options: ["22.50%", "12.50%", "19.79%", "22.88%"], answer: 3, explanation: "Units = 1,000 + 1,200 ÷ 13 = 1,092.31; value = 1,092.31 × 13.50 = 14,746.15; return = 2,746.15 ÷ 12,000 = 22.88%." },
    { id: "afm-054", chapter: "8. Mutual Funds", prompt: "During a year a scheme's NAV fell from ₹18.00 to ₹16.20 while it distributed ₹2.50 per unit. What was the investor's holding period return (two decimals)?", options: ["−10.00%", "3.89%", "13.89%", "4.32%"], answer: 1, explanation: "Return = (16.20 − 18.00 + 2.50) ÷ 18.00 = 0.70 ÷ 18 = 3.89%; the NAV fall is more than offset by the distribution. 4.32% divides by the end NAV." },
    { id: "afm-055", chapter: "8. Mutual Funds", prompt: "Which of the following statements about exchange-traded funds (ETFs) is NOT correct?", options: ["ETF units trade on the stock exchange at market prices throughout the day", "Retail investors ordinarily buy and redeem ETF units directly with the AMC at the day's closing NAV", "Authorised participants and market makers help keep the ETF price close to its NAV", "ETFs usually have lower expense ratios than actively managed funds"], answer: 1, explanation: "Retail investors trade ETF units on the exchange at market prices; direct creation and redemption with the AMC is mainly for authorised participants and large investors." },
    { id: "afm-056", chapter: "9. Derivatives Analysis and Valuation", prompt: "An index is at 1,500. The continuously compounded risk-free rate is 8% a year and the dividend yield is 2% a year (continuous). What is the 6-month futures price (two decimals)?", options: ["1,561.22", "1,545.68", "1,530.30", "1,590.00"], answer: 1, explanation: "F = 1,500 × e^((0.08 − 0.02) × 0.5) = 1,500 × e^0.03 = 1,545.68. 1,561.22 ignores the dividend yield." },
    { id: "afm-057", chapter: "9. Derivatives Analysis and Valuation", prompt: "A share trades at ₹400 and will pay a dividend of ₹10 in 3 months. The continuously compounded risk-free rate is 6% a year. What is the fair 6-month forward price (two decimals)?", options: ["₹412.18", "₹401.88", "₹402.03", "₹392.18"], answer: 2, explanation: "PV of dividend = 10 × e^(−0.015) = 9.85; F = (400 − 9.85) × e^0.03 = ₹402.03. ₹412.18 ignores the dividend." },
    { id: "afm-058", chapter: "9. Derivatives Analysis and Valuation", prompt: "A share is at ₹1,000 and pays no dividend. The 3-month futures trade at ₹1,040 and the risk-free rate is 10% a year (simple). What arbitrage is available per share?", options: ["Short the share, lend and buy futures, earning ₹15", "Borrow, buy the share and sell futures, earning ₹40", "Borrow, buy the share and sell futures, earning ₹15", "Short the share, lend and buy futures, earning ₹40"], answer: 2, explanation: "Fair price = 1,000 × (1 + 0.10 × 3/12) = 1,025; futures are overpriced by 15, so do cash-and-carry: buy spot with borrowed money and sell futures." },
    { id: "afm-059", chapter: "9. Derivatives Analysis and Valuation", prompt: "A fund manager holds ₹5 crore of shares with a beta of 1.2. Index futures are at 20,000 with a contract multiplier of 50. How many contracts should be sold to reduce the portfolio beta to 0.6?", options: ["30", "60", "25", "36"], answer: 0, explanation: "Contracts = 5,00,00,000 × (1.2 − 0.6) ÷ (20,000 × 50) = 3,00,00,000 ÷ 10,00,000 = 30. Selling 60 would hedge fully to beta zero." },
    { id: "afm-060", chapter: "9. Derivatives Analysis and Valuation", prompt: "A share trades at ₹96. A 1-year European call with strike ₹105 costs ₹8, and the 1-year risk-free rate is 5% (annual compounding). By put-call parity, what should the matching European put cost?", options: ["₹4", "₹12", "₹17", "₹3"], answer: 1, explanation: "P = C + PV(K) − S = 8 + 105/1.05 − 96 = 8 + 100 − 96 = ₹12. ₹17 uses K undiscounted (8 + 105 − 96)." },
    { id: "afm-061", chapter: "9. Derivatives Analysis and Valuation", prompt: "A share is at ₹100 and in one period will be ₹120 or ₹90. The risk-free rate is 5% per period. What is the value of a one-period European call with strike ₹105 (two decimals)?", options: ["₹7.50", "₹5.36", "₹7.14", "₹10.00"], answer: 2, explanation: "p = (1.05 − 0.90) ÷ (1.20 − 0.90) = 0.5; call = (0.5 × 15 + 0.5 × 0) ÷ 1.05 = ₹7.14. ₹7.50 forgets to discount." },
    { id: "afm-062", chapter: "9. Derivatives Analysis and Valuation", prompt: "A share is at ₹50 and in one period will be ₹60 or ₹40. The risk-free rate is 4% per period. What is the value of a one-period European put with strike ₹52 (two decimals)?", options: ["₹6.92", "₹4.62", "₹4.80", "₹5.54"], answer: 1, explanation: "p = (1.04 − 0.8) ÷ 0.4 = 0.6; put pays 0 up and 12 down; value = 0.4 × 12 ÷ 1.04 = ₹4.62. ₹6.92 wrongly weights the down state by 0.6." },
    { id: "afm-063", chapter: "9. Derivatives Analysis and Valuation", prompt: "For a European call, S = ₹100, K = ₹100, r = 10% (continuous), σ = 20% and T = 1 year, giving d1 = 0.60 and d2 = 0.40. If N(0.60) = 0.7257 and N(0.40) = 0.6554, what is the Black-Scholes value (two decimals)?", options: ["₹13.27", "₹7.03", "₹16.10", "₹9.65"], answer: 0, explanation: "C = 100 × 0.7257 − 100e^(−0.10) × 0.6554 = 72.57 − 90.48 × 0.6554 = ₹13.27. ₹7.03 forgets to discount the strike." },
    { id: "afm-064", chapter: "9. Derivatives Analysis and Valuation", prompt: "An investor buys a ₹100 call for ₹6 and sells a ₹110 call for ₹2 on the same share and expiry. Which of the following is correct at expiry?", options: ["Maximum profit ₹6, maximum loss ₹4, breakeven ₹104", "Maximum profit ₹10, maximum loss ₹4, breakeven ₹104", "Maximum profit ₹6, maximum loss ₹4, breakeven ₹106", "Maximum profit ₹4, maximum loss ₹6, breakeven ₹108"], answer: 0, explanation: "Net debit = 4 (max loss); max profit = (110 − 100) − 4 = 6; breakeven = lower strike + net debit = ₹104." },
    { id: "afm-065", chapter: "9. Derivatives Analysis and Valuation", prompt: "An investor buys a call and a put on the same share, both with strike ₹200 and the same expiry, paying ₹12 for the call and ₹9 for the put. What are the breakeven prices at expiry?", options: ["₹179 and ₹221", "₹188 and ₹212", "₹191 and ₹209", "₹179 and ₹212"], answer: 0, explanation: "Total premium = 21; a long straddle breaks even at 200 − 21 = ₹179 and 200 + 21 = ₹221." },
    { id: "afm-066", chapter: "9. Derivatives Analysis and Valuation", prompt: "A long butterfly is built by buying one ₹90 call at ₹14, selling two ₹100 calls at ₹7 each and buying one ₹110 call at ₹3 (same expiry). What is the maximum profit?", options: ["₹10", "₹3", "₹13", "₹7"], answer: 3, explanation: "Net cost = 14 − 14 + 3 = 3; maximum payoff is 10 at a price of 100, so maximum profit = 10 − 3 = ₹7. ₹3 is the maximum loss." },
    { id: "afm-067", chapter: "9. Derivatives Analysis and Valuation", prompt: "A trader buys one futures contract of 500 units at ₹2,000. Initial margin is ₹1,00,000 and maintenance margin ₹75,000. The price falls to ₹1,940 at the next settlement. If a margin call requires the account to be restored to the initial margin, what variation margin must be paid?", options: ["₹30,000", "₹5,000", "₹25,000", "Nil"], answer: 0, explanation: "Loss = 60 × 500 = 30,000, leaving ₹70,000, below maintenance; the account must be restored to the initial ₹1,00,000, so ₹30,000 is paid." },
    { id: "afm-068", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "The spot rate is ₹83.20/US$ and the 3-month forward rate is ₹83.82/US$. What is the annualised forward premium on the US dollar (two decimals)?", options: ["0.75%", "2.96%", "8.94%", "2.98%"], answer: 3, explanation: "Premium = (83.82 − 83.20) ÷ 83.20 × 12/3 × 100 = 2.98% p.a. 0.75% is not annualised; 2.96% divides by the forward rate." },
    { id: "afm-069", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "The spot rate is ₹83.00/US$. Six-month interest rates are 7% p.a. in India and 4.5% p.a. in the US. What 6-month forward rate is consistent with interest rate parity (four decimals)?", options: ["₹84.0147/US$", "₹85.0750/US$", "₹81.9976/US$", "₹84.9856/US$"], answer: 0, explanation: "F = 83 × (1 + 0.07 × 6/12) ÷ (1 + 0.045 × 6/12) = 83 × 1.035 ÷ 1.0225 = ₹84.0147; the higher-rate currency (₹) trades at a forward discount." },
    { id: "afm-070", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "A bank quotes ₹/US$ 83.10–83.20 and US$/€ 1.0850–1.0860. What is the implied ₹/€ two-way quote (four decimals)?", options: ["₹90.1635–90.2720/€", "₹90.2720–90.3552/€", "₹76.5193–76.6728/€", "₹90.1635–90.3552/€"], answer: 3, explanation: "Bid ₹/€ = 83.10 × 1.0850 = 90.1635 (bid × bid); ask = 83.20 × 1.0860 = 90.3552 (ask × ask). The spread must widen, not narrow." },
    { id: "afm-071", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "A dealer quotes ₹/US$ 83.10–83.20 and ¥/US$ 150.00–150.50. What is the implied two-way quote in ₹ per ¥100 (two decimals)?", options: ["₹55.22–55.47", "₹55.40–55.28", "₹55.28–55.40", "₹55.32–55.37"], answer: 0, explanation: "Bid ₹/¥ = 83.10 ÷ 150.50 and ask = 83.20 ÷ 150.00; per ¥100 that is 55.22–55.47. Dividing bid by bid gives a reversed spread." },
    { id: "afm-072", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "Spot is ₹80.00/US$ and the 1-year forward is ₹82.00/US$. One-year interest rates are 6% in India and 2% in the US (borrowing and lending at the same rate). What covered interest arbitrage profit is available on borrowing US$10,00,000?", options: ["₹11,60,000 by borrowing ₹, investing in US$ and selling US$ forward", "₹31,37,255 by borrowing US$, investing in ₹ and buying US$ forward", "₹20,00,000 by borrowing US$, investing in ₹ and buying US$ forward", "₹11,60,000 by borrowing US$, investing in ₹ and buying US$ forward"], answer: 3, explanation: "Per US$: ₹80 × 1.06 = ₹84.80 at year end; repaying US$1.02 costs 1.02 × 82 = ₹83.64; gain ₹1.16 × 10,00,000 = ₹11,60,000." },
    { id: "afm-073", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "An exporter will receive US$1,00,000 in 3 months and uses a money market hedge. Spot is ₹83.00–83.10/US$. It can borrow US$ at 6% p.a. and deposit ₹ at 7% p.a. What will it have in ₹ at the end of 3 months (nearest rupee, no intermediate rounding)?", options: ["₹83,20,443", "₹83,30,468", "₹81,77,340", "₹83,14,700"], answer: 0, explanation: "Borrow 1,00,000 ÷ 1.015 = US$98,522.17; sell at bid 83.00 = ₹81,77,340; invest at 1.75% = ₹83,20,443. Using the ask (83.10) gives 83,30,468." },
    { id: "afm-074", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "An importer must pay US$50,000 in 3 months. It buys a call option on US$ with strike ₹83.80 for a premium of ₹0.40 per US$ (ignore interest on the premium). What is the total ₹ outflow if the spot rate at maturity is ₹83.00/US$?", options: ["₹42,10,000", "₹41,50,000", "₹41,70,000", "₹42,00,000"], answer: 2, explanation: "Spot (83.00) is below the strike, so let the call lapse and buy at spot: (83.00 + 0.40) × 50,000 = ₹41,70,000; exercising would cost ₹42,10,000." },
    { id: "afm-075", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "A Mumbai bank quotes ₹83.40–83.60/US$. What is the equivalent indirect quote in US$ per ₹100 (five decimals)?", options: ["US$1.19904–1.19617", "US$1.19904–1.20192", "US$1.19617–1.19904", "US$1.19332–1.19617"], answer: 2, explanation: "Inverting swaps the sides: bid = 100 ÷ 83.60 = 1.19617 and ask = 100 ÷ 83.40 = 1.19904, keeping bid below ask." },
    { id: "afm-076", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "Spot is ₹83.00/US$. Expected inflation is 5% in India and 2.5% in the US for the next year. Under relative purchasing power parity, what is the expected spot rate in one year (two decimals)?", options: ["₹85.02/US$", "₹81.02/US$", "₹85.08/US$", "₹87.15/US$"], answer: 0, explanation: "Expected spot = 83 × 1.05 ÷ 1.025 = ₹85.02; the higher-inflation currency (₹) depreciates. 85.08 uses the 2.5% approximation." },
    { id: "afm-077", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "An Indian manufacturer has no foreign-currency receivables or payables, but a sustained appreciation of the rupee makes its domestic products costlier than imported rivals and erodes its future cash flows. This is best described as:", options: ["Transaction exposure", "Economic (operating) exposure", "Translation exposure", "Settlement risk"], answer: 1, explanation: "The change in future cash flows from competitive effects of exchange rates is economic exposure; with no foreign-currency contracts there is no transaction exposure." },
    { id: "afm-078", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "Spot is ₹83.15–83.25/US$. The 1-month swap points are 10/15, and the 3-month swap points are 25/20. What are the outright 1-month and 3-month forward quotes?", options: ["1-month ₹83.25–83.40; 3-month ₹82.90–83.05", "1-month ₹83.05–83.10; 3-month ₹83.40–83.45", "1-month ₹83.25–83.40; 3-month ₹83.40–83.45", "1-month ₹83.05–83.10; 3-month ₹82.90–83.05"], answer: 0, explanation: "Ascending points (10/15) are a premium and are added; descending points (25/20) are a discount and are subtracted from spot." },
    { id: "afm-079", chapter: "10. Foreign Exchange Exposure and Risk Management", prompt: "An exporter booked a forward contract to sell US$1,00,000 to its bank at ₹84.00. On the due date it cancels the contract as the buyer defaulted. The spot rate is then ₹84.40–84.50/US$. Applying FEDAI rules for cancellation on the due date and ignoring charges, what is the settlement?", options: ["Exporter pays the bank ₹50,000", "Exporter pays the bank ₹40,000", "Bank pays the exporter ₹50,000", "Bank pays the exporter ₹40,000"], answer: 0, explanation: "On cancellation the bank sells US$ to the customer at its spot selling rate ₹84.50 and buys at the contract rate ₹84.00; the 0.50 × 1,00,000 loss falls on the exporter." },
    { id: "afm-080", chapter: "11. International Financial Management", prompt: "An Indian firm expects US$1,00,000 from a US project in one year. Spot is ₹83/US$; risk-free rates are 8% in India and 4% in the US; the project's ₹ discount rate is 12%. Using the home-currency approach with an IRP forward rate, what is the PV in ₹ (nearest rupee)?", options: ["₹74,10,714", "₹76,95,742", "₹79,80,769", "₹77,57,576"], answer: 1, explanation: "F = 83 × 1.08 ÷ 1.04 = 86.1923; ₹ flow = 86,19,231; PV at 12% = ₹76,95,742. ₹74,10,714 converts at spot (83,00,000 ÷ 1.12)." },
    { id: "afm-081", chapter: "11. International Financial Management", prompt: "An Indian company borrows US$10 million for one year at 5% when spot is ₹83/US$. The rupee depreciates so that the rate at repayment is ₹85.49/US$. What is the effective rupee cost of the loan (two decimals)?", options: ["8.15%", "8.00%", "5.00%", "2.00%"], answer: 0, explanation: "₹85.49 ÷ 83 = 1.03; effective cost = 1.05 × 1.03 − 1 = 8.15%. 8% simply adds 5% and 3% and ignores the cross term." },
    { id: "afm-082", chapter: "11. International Financial Management", prompt: "An Indian company issues bonds in Japan, denominated in yen, to Japanese investors. Such a bond is best described as a:", options: ["Eurobond", "Yankee bond", "Samurai bond (a foreign bond)", "Bulldog bond"], answer: 2, explanation: "A bond issued by a non-resident in the local market and currency is a foreign bond; in Japan it is a Samurai bond. A Eurobond is issued outside the currency's home market." },
    { id: "afm-083", chapter: "11. International Financial Management", prompt: "Within a group, A owes B $50m, B owes C $30m, C owes A $40m and B owes A $10m. After multilateral netting through a netting centre, what is the total amount actually transferred?", options: ["$10m", "$130m", "$40m", "$20m"], answer: 0, explanation: "Net positions: A 50 − 50 = 0; B 50 − 40 = +10; C 30 − 40 = −10. Only C pays $10m (to B), against $130m of gross transfers." },
    { id: "afm-084", chapter: "11. International Financial Management", prompt: "Which of the following statements about depository receipts is NOT correct?", options: ["ADRs are denominated in US dollars and traded in the US", "An Indian company raises rupee funds in India by issuing Indian Depository Receipts", "GDRs can be listed and traded in more than one foreign market", "IDRs are issued in India by companies incorporated outside India"], answer: 1, explanation: "IDRs are issued by foreign companies to raise funds in India; an Indian company tapping overseas investors uses ADRs or GDRs." },
    { id: "afm-085", chapter: "11. International Financial Management", prompt: "An Indian investor's US stock rises 8% in dollar terms over a year, while the US dollar appreciates 4% against the rupee. What is the investor's return in rupees (two decimals)?", options: ["12.32%", "12.00%", "4.00%", "3.85%"], answer: 0, explanation: "₹ return = (1.08 × 1.04) − 1 = 12.32%; the currency gain applies to the grown dollar value, so simply adding (12%) understates it." },
    { id: "afm-086", chapter: "12. Interest Rate Risk Management", prompt: "A company buys a 3 × 6 FRA on ₹10 crore at 7.00% p.a. At the fixing date the 3-month reference rate is 7.80% p.a. Settlement is made at the start of the FRA period, discounted at the reference rate (use 3/12 of a year). What is the settlement (nearest rupee)?", options: ["Company receives ₹1,96,175", "Company pays ₹1,96,175", "Company receives ₹2,00,000", "Company pays ₹2,00,000"], answer: 0, explanation: "Interest difference = 10 crore × 0.80% × 0.25 = 2,00,000; discounted ÷ (1 + 0.078 × 0.25) = ₹1,96,175. The FRA buyer gains when rates rise." },
    { id: "afm-087", chapter: "12. Interest Rate Risk Management", prompt: "Company A can borrow at a fixed 8% or at MIBOR + 0.5%; Company B at a fixed 9.5% or at MIBOR + 1.0%. A wants floating and B wants fixed. What is the total potential saving from an interest rate swap?", options: ["1.5%", "0.5%", "1.0%", "2.0%"], answer: 2, explanation: "Fixed spread 1.5% less floating spread 0.5% = 1.0% quality spread differential; A borrows fixed and B floating, then they swap." },
    { id: "afm-088", chapter: "12. Interest Rate Risk Management", prompt: "A firm pays fixed 7% and receives floating on a ₹100 crore swap with 2 annual payments left, valued just after a reset. Spot rates are 6% (1 year) and 6.5% (2 years). What is the swap's value to the fixed-rate payer?", options: ["An asset of ₹94.13 lakh", "A liability of ₹1.88 crore", "An asset of ₹1.88 crore", "A liability of ₹94.13 lakh"], answer: 3, explanation: "Fixed leg = 7/1.06 + 107/1.065² = 100.9413 crore; floating leg = 100 at reset; fixed payer's value = 100 − 100.9413 = −₹94.13 lakh." },
    { id: "afm-089", chapter: "12. Interest Rate Risk Management", prompt: "A borrower holds an interest rate cap at 8% on a ₹50 crore floating-rate loan with quarterly resets. If the reference rate for a quarter is set at 9.2%, what does the cap pay for that quarter (ignore day-count and discounting)?", options: ["₹15,00,000", "₹60,00,000", "₹1,15,00,000", "₹5,00,000"], answer: 0, explanation: "Payment = 50 crore × (9.2% − 8%) × 3/12 = ₹15,00,000. ₹60,00,000 is the full-year amount." },
    { id: "afm-090", chapter: "12. Interest Rate Risk Management", prompt: "A floating-rate borrower buys a cap at 9% and sells a floor at 6% on its loan. Ignoring premiums and any spread, what will be its effective borrowing rate if the reference rate falls to 5%?", options: ["5%", "6%", "9%", "7.5%"], answer: 1, explanation: "Below the floor the borrower, as floor seller, pays the 1% shortfall to the buyer, so its cost cannot fall below 6%." },
    { id: "afm-091", chapter: "12. Interest Rate Risk Management", prompt: "A bank has assets of ₹500 crore with duration 4 years and liabilities of ₹450 crore with duration 2.5 years. Rates are 8%. Using duration gap analysis, what is the approximate change in equity value if rates rise by 1%?", options: ["Fall of ₹7.50 crore", "Fall of ₹8.10 crore", "Rise of ₹8.10 crore", "Fall of ₹8.75 crore"], answer: 1, explanation: "Gap = 4 − (450/500) × 2.5 = 1.75; ΔE = −1.75 × 500 × 0.01 ÷ 1.08 = −₹8.10 crore. ₹8.75 crore ignores the 1 + y adjustment." },
    { id: "afm-092", chapter: "12. Interest Rate Risk Management", prompt: "A company with floating-rate debt fears that interest rates will rise. Which of the following would NOT protect it?", options: ["Buying an interest rate cap", "Entering a swap to pay fixed and receive floating", "Buying an interest rate floor", "Buying an FRA"], answer: 2, explanation: "A floor pays when rates fall, which protects lenders, not borrowers; a cap, a pay-fixed swap or a bought FRA all gain when rates rise." },
    { id: "afm-093", chapter: "13. Business Valuation", prompt: "Comparable companies trade at 8 times EV/EBITDA. A target has EBITDA of ₹50 crore, debt of ₹120 crore, cash of ₹20 crore and 10 crore shares. What is the implied value per share?", options: ["₹28", "₹40", "₹26", "₹30"], answer: 3, explanation: "EV = 8 × 50 = 400; equity = 400 − 120 + 20 = ₹300 crore; per share ₹30. ₹28 deducts debt but ignores cash." },
    { id: "afm-094", chapter: "13. Business Valuation", prompt: "A company has EBIT of ₹60 crore, a tax rate of 25%, capital employed of ₹300 crore and a WACC of 12%. What is its Economic Value Added?", options: ["₹9 crore", "₹24 crore", "₹45 crore", "−₹6 crore"], answer: 0, explanation: "NOPAT = 60 × 0.75 = 45; capital charge = 300 × 12% = 36; EVA = 45 − 36 = ₹9 crore. ₹24 crore uses pre-tax EBIT." },
    { id: "afm-095", chapter: "13. Business Valuation", prompt: "A firm's book assets are ₹500 crore, but land is worth ₹80 crore more than book value. Outside liabilities are ₹200 crore and preference share capital is ₹50 crore. There are 10 crore equity shares. What is the net asset value per equity share?", options: ["₹38", "₹30", "₹25", "₹33"], answer: 3, explanation: "Equity value = 500 + 80 − 200 − 50 = ₹330 crore; ÷ 10 crore shares = ₹33. ₹38 forgets to deduct preference capital." },
    { id: "afm-096", chapter: "13. Business Valuation", prompt: "In a DCF model, FCFF in year 5 is ₹100 crore, growth thereafter is 4% for ever and WACC is 11%. What is the terminal value at the end of year 5 (two decimals)?", options: ["₹1,428.57 crore", "₹945.45 crore", "₹1,485.71 crore", "₹1,545.14 crore"], answer: 2, explanation: "TV₅ = FCFF₆ ÷ (WACC − g) = 100 × 1.04 ÷ 0.07 = ₹1,485.71 crore; using FCFF₅ (₹1,428.57 crore) misses one year of growth." },
    { id: "afm-097", chapter: "13. Business Valuation", prompt: "Which valuation approach values a diversified company by valuing each business segment with multiples of focused peer companies in that industry and adding them up?", options: ["Chop-shop (break-up) approach", "Dividend discount approach", "Adjusted net asset approach", "Economic value added approach"], answer: 0, explanation: "The chop-shop method values each segment with pure-play industry multiples to find whether the conglomerate is worth more broken up." },
    { id: "afm-098", chapter: "13. Business Valuation", prompt: "The present value of a company's operating FCFF is ₹1,500 crore. It has debt (market value) of ₹400 crore, surplus cash of ₹50 crore and non-operating investments of ₹30 crore. What is the value of equity?", options: ["₹1,180 crore", "₹1,100 crore", "₹1,120 crore", "₹1,980 crore"], answer: 0, explanation: "Equity = 1,500 + 50 + 30 − 400 = ₹1,180 crore; non-operating assets add to operating value before deducting debt." },
    { id: "afm-099", chapter: "14. Mergers, Acquisitions and Corporate Restructuring", prompt: "Acquirer A has earnings of ₹120 crore, 10 crore shares and a share price of ₹180. Target T has earnings of ₹40 crore, 5 crore shares and a share price of ₹90. If shares are exchanged on market price and there is no synergy, what is A's post-merger EPS?", options: ["₹12.80", "₹12.00", "₹13.33", "₹12.31"], answer: 0, explanation: "Swap ratio = 90 ÷ 180 = 0.5; new shares = 2.5 crore; EPS = 160 ÷ 12.5 = ₹12.80. ₹12.00 results from an EPS-based ratio (0.667)." },
    { id: "afm-100", chapter: "14. Mergers, Acquisitions and Corporate Restructuring", prompt: "Using the same data (A: earnings ₹120 crore, 10 crore shares; T: earnings ₹40 crore, 5 crore shares), the merger is expected to create synergy that lifts combined earnings to ₹172 crore. What is the maximum exchange ratio at which A's EPS of ₹12 is not diluted?", options: ["0.6667", "0.5000", "0.8667", "0.9333"], answer: 2, explanation: "Shares allowed = 172 ÷ 12 = 14.333 crore; new shares = 4.333 crore for 5 crore T shares = 0.8667. 0.6667 ignores synergy." },
    { id: "afm-101", chapter: "14. Mergers, Acquisitions and Corporate Restructuring", prompt: "A (earnings ₹120 crore, 10 crore shares, price ₹180) acquires T (earnings ₹40 crore, 5 crore shares). The market will value the combined firm at a P/E of 14 with no synergy. What is the maximum exchange ratio that keeps A's share price at ₹180 (four decimals)?", options: ["0.5000", "0.6667", "0.4444", "0.4889"], answer: 3, explanation: "Combined value = 160 × 14 = 2,240 crore; shares allowed = 2,240 ÷ 180 = 12.444 crore; new shares 2.444 ÷ 5 = 0.4889." },
    { id: "afm-102", chapter: "14. Mergers, Acquisitions and Corporate Restructuring", prompt: "A is worth ₹1,800 crore and T ₹450 crore as stand-alone firms; together they will be worth ₹2,500 crore. A pays ₹520 crore in cash for T. What is the NPV of the acquisition to A's shareholders?", options: ["₹180 crore", "₹250 crore", "₹70 crore", "₹200 crore"], answer: 0, explanation: "Synergy = 2,500 − 2,250 = 250; premium = 520 − 450 = 70; NPV to A = 250 − 70 = ₹180 crore. ₹70 crore is T's gain, not A's." },
    { id: "afm-103", chapter: "14. Mergers, Acquisitions and Corporate Restructuring", prompt: "A (worth ₹1,800 crore, 10 crore shares) acquires T (worth ₹450 crore) by issuing 3 crore new shares. The combined firm will be worth ₹2,500 crore. What is the true cost of the acquisition to A (two decimals)?", options: ["₹540.00 crore", "₹450.00 crore", "₹750.00 crore", "₹576.92 crore"], answer: 3, explanation: "T's holders own 3/13 of ₹2,500 crore = ₹576.92 crore. Valuing the shares at A's pre-deal price (3 × 180 = 540) ignores that T's holders share the synergy." },
    { id: "afm-104", chapter: "14. Mergers, Acquisitions and Corporate Restructuring", prompt: "Which of the following statements about 'bootstrapping' of EPS in mergers is correct?", options: ["Bootstrapping EPS growth always increases the acquirer's share price", "A high-P/E acquirer buying a low-P/E target in a share exchange can raise EPS without creating any real value", "Bootstrapping requires the target to have a higher P/E than the acquirer", "Bootstrapping arises only in cash acquisitions"], answer: 1, explanation: "Issuing high-P/E shares for low-P/E earnings lifts EPS mechanically; if the market applies a lower blended P/E, price does not rise." },
    { id: "afm-105", chapter: "14. Mergers, Acquisitions and Corporate Restructuring", prompt: "A parent company wants to separate a subsidiary and raise cash from it at the same time. Which restructuring route achieves this?", options: ["Spin-off to existing shareholders", "Equity carve-out (selling a minority stake to the public)", "Split-off through a share exchange", "Tracking stock distributed as a dividend"], answer: 1, explanation: "In a carve-out the subsidiary's shares are sold to new investors, bringing in cash; a spin-off distributes shares pro rata and raises nothing." },
    { id: "afm-106", chapter: "14. Mergers, Acquisitions and Corporate Restructuring", prompt: "A target company responds to a hostile bid by launching its own offer to acquire the bidder. This defence is known as:", options: ["White knight", "Crown jewel defence", "Poison pill", "Pac-Man defence"], answer: 3, explanation: "In a Pac-Man defence the target turns the tables by bidding for the acquirer; a white knight is a friendly third-party bidder." },
    { id: "afm-107", chapter: "15. Startup Finance", prompt: "A venture capital fund invests ₹5 crore in a startup in return for a 20% stake (fully diluted). What is the pre-money valuation?", options: ["₹25 crore", "₹20 crore", "₹4 crore", "₹30 crore"], answer: 1, explanation: "Post-money = 5 ÷ 20% = ₹25 crore; pre-money = 25 − 5 = ₹20 crore." },
    { id: "afm-108", chapter: "15. Startup Finance", prompt: "Founders own 100% of a startup. They sell 15% in a seed round and then a further 25% of the enlarged company in a Series A round (new shares issued each time). What is the founders' stake after Series A?", options: ["60.00%", "75.00%", "63.75%", "85.00%"], answer: 2, explanation: "Each round dilutes all existing holders proportionately: 100% × 0.85 × 0.75 = 63.75%. Simply subtracting 15% and 25% gives 60%." },
    { id: "afm-109", chapter: "15. Startup Finance", prompt: "A VC expects a startup to be worth ₹200 crore at exit in 5 years and requires a 50% annual return. Under the VC method, what ownership must it get for a ₹10 crore investment today (two decimals, no further dilution)?", options: ["5.00%", "25.00%", "12.66%", "37.97%"], answer: 3, explanation: "Required exit value = 10 × 1.5⁵ = ₹75.94 crore; stake = 75.94 ÷ 200 = 37.97%. 5% ignores the required return." },
    { id: "afm-110", chapter: "15. Startup Finance", prompt: "Which of the following is NOT a feature of bootstrapping a startup?", options: ["Funding growth from the founders' own savings", "Raising the first round from institutional venture capital funds", "Using customer advances and early revenue to finance operations", "Keeping costs low to stretch limited internal funds"], answer: 1, explanation: "Bootstrapping means growing with internal funds, founders' money and customer cash; institutional VC funding is external equity." },
  ]
};
export default bank;
